/**
 * preview.html's tokens are DESIGN.md's front matter, regenerated by `tools/design-preview.mjs`: a
 * token changed in one and not the other fails here, with the command that fixes it.
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { readFrontMatter, regenerate } from './design-preview.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const design = readFileSync(join(root, 'DESIGN.md'), 'utf8');
const preview = readFileSync(join(root, 'preview.html'), 'utf8');

describe('preview.html', () => {
  it('carries the front matter as it is now (run node tools/design-preview.mjs)', () => {
    expect(regenerate(design, preview) === preview).toBe(true);
  });

  it('has both schemes, a touch block and a scheme toggle', () => {
    expect(preview).toContain(":root[data-scheme='light'] {");
    expect(preview).toContain('@media (prefers-color-scheme: light)');
    expect(preview).toContain('@media (pointer: coarse)');
    expect(preview).toMatch(/role="radiogroup" aria-label="colour scheme"/);
  });

  it('shows the resize handle, the collapsed handle, the tooltip and More', () => {
    expect(preview).toContain('role="separator"');
    expect(preview).toContain('aria-label="show sidebar"');
    expect(preview).toContain('role="tooltip"');
    expect(preview).toContain('aria-label="more"');
    // The chrome's tooltips, not the browser's.
    expect(preview).not.toMatch(/\stitle="/);
  });
});

describe('readFrontMatter', () => {
  it('reads the maps, quoted values and the block scalar', () => {
    const front = readFrontMatter(design);
    expect(front.colors.primary).toBe('#8fb7e8');
    expect(front['colors-light'].primary).toBe('#1f5fae');
    expect(front.typography.body.fontSize).toBe('11.5px');
    expect(front.description).toContain('dense');
  });
});
